                                        var sales = _tallyConnector.MapVouchersToSales(salesVouchers, company.Name);
                                        var salesFlat = sales.Select(s => new {
                                            id = DeterministicGuidOrFallback(s.Id),
                                            voucher_id = DeterministicGuidOrFallback(s.VoucherId ?? s.Id),
                                            company_id = companyUuid,
                                            owner_id = currentOwnerId,
                                            invoice_number = s.InvoiceNumber, invoice_date = s.InvoiceDate,
                                            party_ledger_id = s.PartyLedgerId, party_ledger_name = s.PartyLedgerName,
                                            party_gstin = s.PartyGstin, place_of_supply = s.PlaceOfSupply,
                                            gross_amount = s.GrossAmount, discount_amount = s.DiscountAmount,
                                            taxable_amount = s.TaxableAmount, cgst_amount = s.CgstAmount,
                                            sgst_amount = s.SgstAmount, igst_amount = s.IgstAmount,
                                            cess_amount = s.CessAmount, round_off = s.RoundOff,
                                            net_amount = s.NetAmount, is_cancelled = s.IsCancelled,
                                            narration = s.Narration, master_id = s.MasterId, alter_id = s.AlterId
                                        }).ToList();
                                        var salesUploadSucceeded = await UploadListAsync("sales", salesFlat, "id");
                                        if (!salesUploadSucceeded) AddLog("[WARN] Skipping sales_items because sales batch failed.");
                                        if (salesUploadSucceeded) salesSynced += salesVouchers.Count;

                                        var salesItems = sales.Where(s => s.Items != null).SelectMany(s => s.Items!).Select(i => new {
                                            id = DeterministicGuidOrFallback(i.Id, $"{i.SaleId}|{i.StockItemName}|{i.Quantity}|{i.Amount}"),
                                            sale_id = DeterministicGuidOrFallback(i.SaleId),
                                            company_id = companyUuid,
                                            owner_id = currentOwnerId,
                                            stock_item_name = i.StockItemName, 
                                            quantity = i.Quantity, 
                                            unit = i.Unit,
                                            rate = i.Rate, 
                                            amount = i.Amount, 
                                            tax_rate = i.TaxRate, 
                                            hsn_code = i.HsnCode,
                                            discount_percent = i.DiscountPercent
                                        }).ToList();
                                        if (salesUploadSucceeded && salesItems.Any()) await UploadListAsync("sales_items", salesItems, "id");
                                        if (salesUploadSucceeded) AddLog($"   {salesVouchers.Count} sales updated locally");
                                        
                                        // TRACK FOR SMART ALERTS
                                        if (salesUploadSucceeded) totalSalesAmountFetched += sales.Sum(s => s.NetAmount);
                                        foreach (var s in (salesUploadSucceeded ? sales.Where(s => s.NetAmount >= HighValueThreshold) : Enumerable.Empty<Sale>()))
                                        {
                                            highValueAlerts.Add($"High Value Sale: <b>{s.PartyLedgerName}</b> - INR {s.NetAmount:N0}");
                                        }
                                    }

                                    // 2. Map existing vouchers to Purchases
                                    var purchaseVouchers = finalVouchers.Where(v => v.VoucherType.Contains("Purchase", StringComparison.OrdinalIgnoreCase)).ToList();
                                    if (purchaseVouchers.Count > 0)
                                    {
                                        var purchases = _tallyConnector.MapVouchersToPurchases(purchaseVouchers, company.Name);
                                        var purchasesFlat = purchases.Select(p => new {
                                            id = DeterministicGuidOrFallback(p.Id),
                                            voucher_id = DeterministicGuidOrFallback(p.VoucherId ?? p.Id),
                                            company_id = companyUuid,
                                            owner_id = currentOwnerId,
                                            invoice_number = p.InvoiceNumber, invoice_date = p.InvoiceDate,
                                            party_ledger_id = p.PartyLedgerId, party_ledger_name = p.PartyLedgerName,
                                            party_gstin = p.PartyGstin, gross_amount = p.GrossAmount,
                                            discount_amount = p.DiscountAmount, taxable_amount = p.TaxableAmount,
                                            cgst_amount = p.CgstAmount, sgst_amount = p.SgstAmount,
                                            igst_amount = p.IgstAmount, cess_amount = p.CessAmount,
                                            round_off = p.RoundOff, net_amount = p.NetAmount,
                                            is_cancelled = p.IsCancelled, narration = p.Narration,
                                            master_id = p.MasterId, alter_id = p.AlterId
                                        }).ToList();
                                        var purchasesUploadSucceeded = await UploadListAsync("purchases", purchasesFlat, "id");
                                        if (!purchasesUploadSucceeded) AddLog("[WARN] Skipping purchase_items because purchases batch failed.");
                                        if (purchasesUploadSucceeded) purchasesSynced += purchaseVouchers.Count;

                                        var purchaseItems = purchases.Where(p => p.Items != null).SelectMany(p => p.Items!).Select(i => new {
                                            id = DeterministicGuidOrFallback(i.Id, $"{i.PurchaseId}|{i.StockItemName}|{i.Quantity}|{i.Amount}"),
                                            purchase_id = DeterministicGuidOrFallback(i.PurchaseId),
                                            company_id = companyUuid,
                                            owner_id = currentOwnerId,
                                            stock_item_name = i.StockItemName, 
                                            quantity = i.Quantity, 
                                            unit = i.Unit,
                                            rate = i.Rate, 
                                            amount = i.Amount, 
                                            tax_rate = i.TaxRate, 
                                            hsn_code = i.HsnCode,
                                            discount_percent = i.DiscountPercent
                                        }).ToList();
                                        if (purchasesUploadSucceeded && purchaseItems.Any()) await UploadListAsync("purchase_items", purchaseItems, "id");
                                        if (purchasesUploadSucceeded) AddLog($"   {purchaseVouchers.Count} purchases updated locally");
                                    }

                                    // 3. Extract Allocations & Notes (Incremental)
                                    var billAllocations = _tallyConnector.ExtractBillAllocations(finalVouchers, company.Name);
                                    if (billAllocations.Count > 0) await UploadListAsync("bill_allocations", billAllocations, "id");

                                    var bankAllocations = _tallyConnector.ExtractBankAllocations(finalVouchers, company.Name);
                                    if (bankAllocations.Count > 0) await UploadListAsync("bank_allocations", bankAllocations, "id");

                                    var notes = _tallyConnector.ExtractDebitCreditNotes(finalVouchers, company.Name);
                                    if (notes.Count > 0) await UploadListAsync("debit_credit_notes", notes, "id");
                                    }
                                }
                            }
                            else
                            {
                                AddLog($"ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã¢â‚¬Â¦ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¦ No voucher modifications detected - data is up to date!");
                            }
                            
                            // 3. OPTIMIZATION: Removed redundant "Last 7 Days" re-fetch.
                            // The AlterID logic above already captures ALL new and modified vouchers efficiently.
                            // Re-fetching recent days caused Tally hangs due to heavy XML generation.
