        private static void EnsureVoucherIds(List<Voucher> vouchers, string companyId)
        {
            foreach (var voucher in vouchers)
            {
                if (voucher == null)
                {
                    continue;
                }

                if (string.IsNullOrWhiteSpace(voucher.VoucherId))
                {
                    voucher.GenerateDeterministicId(companyId);
                }
                else if (!Guid.TryParse(voucher.VoucherId, out _))
                {
                    voucher.VoucherId = ApiClient.GenerateDeterministicGuid(voucher.VoucherId).ToString();
                }
            }
        }

        private static string DeterministicGuidOrFallback(params string?[] seeds)
        {
            var normalized = seeds
                .Where(s => !string.IsNullOrWhiteSpace(s))
                .Select(s => s!.Trim())
                .Distinct(StringComparer.Ordinal)
                .ToList();

            if (normalized.Count == 1 && Guid.TryParse(normalized[0], out var existingGuid))
            {
                return existingGuid.ToString();
            }

            var seed = normalized.Count > 0
                ? string.Join("|", normalized)
                : Guid.NewGuid().ToString("N");

            return ApiClient.GenerateDeterministicGuid(seed).ToString();
        }

        /// <summary>
        /// Split list into batches
        /// </summary>
        private static List<List<T>> ChunkList<T>(List<T> list, int chunkSize)
        {
            var chunks = new List<List<T>>();
            for (int i = 0; i < list.Count; i += chunkSize)
            {
                chunks.Add(list.GetRange(i, Math.Min(chunkSize, list.Count - i)));
            }
            return chunks;
        }

        /// <summary>
        /// Helper to get display name from any Tally model
        /// </summary>
        private string GetItemDisplayName(object item)
        {
            if (item == null) return "Unknown";
            
            // Try to find Name, VoucherNumber, or InvoiceNumber property
            var type = item.GetType();
            var nameProp = type.GetProperty("Name") ?? 
                           type.GetProperty("VoucherNumber") ?? 
                           type.GetProperty("InvoiceNumber");
            
            if (nameProp != null)
            {
                return nameProp.GetValue(item)?.ToString() ?? "Unnamed";
            }

            return item.ToString() ?? "Unnamed";
        }

        // ============================================
        // TWO-WAY SYNC: Push Cloud entries TO Tally
        // ============================================

        /// <summary>
        /// Process pending transactions from Cloud and push them to Tally
        /// Called when Tally is open and sync runs
        /// </summary>
        private async Task ProcessPendingTransactionsAsync(Company company)
        {
            try
            {
                if (_apiClient == null || _tallyConnector == null) return;

                var pending = await _apiClient.GetPendingTransactionsAsync(company.Id);
                if (pending.Count == 0)
                {
                    return;
                }

                AddLog($"Found {pending.Count} pending entries to push to Tally");
                UpdateStatus(SyncState.Syncing, $"Pushing {pending.Count} entries to Tally...");

                int successCount = 0;
                int failCount = 0;

                foreach (var transaction in pending)
                {
                    var currentAttempt = GetRetryAttempt(transaction);

                    try
                    {
                        await _apiClient.UpdatePendingTransactionStatusAsync(
                            transaction.Id,
                            "processing",
                            null,
                            null,
                            currentAttempt);
                        JToken? voucherToken = ToJToken((object?)transaction.VoucherData);
                        if (voucherToken == null)
                        {
                            var nextAttempt = currentAttempt + 1;
                            var nextStatus = nextAttempt < MaxPendingPushRetries ? "pending" : "failed";
                            var retryError = AppendRetryMetadata("No voucher data provided", nextAttempt);

                            await _apiClient.UpdatePendingTransactionStatusAsync(
                                transaction.Id,
                                nextStatus,
                                null,
                                retryError,
                                nextAttempt);
                            failCount++;
                            continue;
                        }

                        string partyLedger = GetTokenString(
                            voucherToken,
                            "party_ledger_name",
                            "partyLedgerName",
                            "party_name",
                            "partyName",
                            "customer_name",
                            "customerName") ?? string.Empty;

                        decimal amount = GetTokenDecimal(
                            voucherToken,
                            "net_amount",
                            "amount",
                            "total_amount",
                            "grand_total",
                            "total",
                            "totalAmount") ?? 0m;

                        var parsedVoucherDate = GetTokenDate(
                            voucherToken,
                            "invoice_date",
                            "invoiceDate",
                            "voucher_date",
                            "voucherDate",
                            "date",
                            "entry_date",
                            "entryDate");

                        DateTime voucherDate;
                        if (parsedVoucherDate.HasValue && IsValidVoucherDate(parsedVoucherDate.Value))
                        {
                            voucherDate = parsedVoucherDate.Value.Date;
                        }
                        else if (IsValidVoucherDate(transaction.CreatedAt))
                        {
                            voucherDate = transaction.CreatedAt.Date;
                            AddLog($"   Voucher date missing/invalid, using created date {voucherDate:dd-MMM-yyyy}");
                        }
                        else
                        {
                            voucherDate = DateTime.Today;
                            AddLog($"   Voucher date missing/invalid, using today {voucherDate:dd-MMM-yyyy}");
                        }

                        string narration = GetTokenString(voucherToken, "narration", "notes", "description", "memo")
                            ?? "Created from TallySync App";

                        string normalizedType = NormalizeTallyVoucherType(transaction.TransactionType, transaction.VoucherData);

                        var inventoryEntries = ExtractInventoryEntries(voucherToken);
                        var ledgerEntries = ExtractLedgerEntries(voucherToken);

                        if (amount <= 0 && inventoryEntries.Count > 0)
                        {
                            amount = inventoryEntries.Sum(entry => Math.Abs(entry.Amount));
                        }

                        if (amount <= 0 && ledgerEntries.Count > 0)
                        {
                            amount = ledgerEntries.Sum(entry => Math.Abs(entry.Amount));
                        }

                        if (string.IsNullOrWhiteSpace(partyLedger))
                        {
                            partyLedger = ledgerEntries
                                .Select(entry => entry.LedgerName)
                                .FirstOrDefault(name => !string.IsNullOrWhiteSpace(name))
                                ?? "Cash";
                        }

                        AddLog($"   Push {normalizedType}: {partyLedger} amount={amount:N2} items={inventoryEntries.Count} ledgers={ledgerEntries.Count}");

                        var (success, voucherNumber, error) = await _tallyConnector.PushVoucherToTallyAsync(
                            company.Name,
                            normalizedType,
                            voucherDate,
                            partyLedger,
                            amount,
                            narration,
                            ledgerEntries.Count > 0 ? ledgerEntries : null,
                            inventoryEntries.Count > 0 ? inventoryEntries : null
                        );

                        if (success)
                        {
                            await _apiClient.UpdatePendingTransactionStatusAsync(transaction.Id, "synced", voucherNumber, null, 0);
                            AddLog($"   Created in Tally: {voucherNumber}");
                            successCount++;
                        }
                        else
                        {
                            if (IsVoucherDateMissingError(error))
                            {
                                var forcedDate = DateTime.Today;
                                AddLog($"   Tally reported missing voucher date. Retrying with forced date {forcedDate:dd-MMM-yyyy}...");

                                var (retrySuccess, retryVoucherNumber, retryErrorMessage) = await _tallyConnector.PushVoucherToTallyAsync(
                                    company.Name,
                                    normalizedType,
                                    forcedDate,
                                    partyLedger,
                                    amount,
                                    narration,
                                    ledgerEntries.Count > 0 ? ledgerEntries : null,
                                    inventoryEntries.Count > 0 ? inventoryEntries : null
                                );

                                if (retrySuccess)
                                {
                                    await _apiClient.UpdatePendingTransactionStatusAsync(transaction.Id, "synced", retryVoucherNumber, null, 0);
                                    AddLog($"   Created in Tally after date retry: {retryVoucherNumber}");
                                    successCount++;
                                    continue;
                                }

                                error = retryErrorMessage ?? error;
                            }

                            var nextAttempt = currentAttempt + 1;
                            var nextStatus = nextAttempt < MaxPendingPushRetries ? "pending" : "failed";
                            var retryError = AppendRetryMetadata(error ?? "Unknown error", nextAttempt);

                            await _apiClient.UpdatePendingTransactionStatusAsync(
                                transaction.Id,
                                nextStatus,
                                null,
                                retryError,
                                nextAttempt);

                            AddLog($"   Failed attempt {nextAttempt}/{MaxPendingPushRetries}: {error}");
                            failCount++;
                        }
                    }
                    catch (Exception ex)
                    {
                        var nextAttempt = currentAttempt + 1;
                        var nextStatus = nextAttempt < MaxPendingPushRetries ? "pending" : "failed";
                        var retryError = AppendRetryMetadata(ex.Message, nextAttempt);

                        await _apiClient.UpdatePendingTransactionStatusAsync(
                            transaction.Id,
                            nextStatus,
                            null,
                            retryError,
                            nextAttempt);

                        failCount++;
                    }

                    await Task.Delay(200);
                }

                if (successCount > 0)
                {
                    AddLog($"Two-Way Sync: {successCount} entries pushed to Tally");
                }

                if (failCount > 0)
                {
                    AddLog($"Two-Way Sync: {failCount} entries failed (retry queued where attempts remain)");
                }
            }
            catch (Exception ex)
            {
                SyncLogger.Log($"ProcessPendingTransactionsAsync error: {ex.Message}");
            }
        }

        private static JToken? ToJToken(object? value)
        {
            if (value == null)
            {
                return null;
            }

            if (value is JToken token)
            {
                return token;
            }

            try
            {
                return JToken.FromObject(value);
            }
            catch
            {
                return null;
            }
        }

        private static string? GetTokenString(JToken? token, params string[] keys)
        {
            if (token == null)
            {
                return null;
            }

            foreach (var key in keys)
            {
                var candidate = token[key];
                if (candidate == null || candidate.Type == JTokenType.Null)
                {
                    continue;
                }

                var text = candidate.ToString().Trim();
                if (!string.IsNullOrWhiteSpace(text))
                {
                    return text;
                }
            }

            return null;
        }

        private static decimal? GetTokenDecimal(JToken? token, params string[] keys)
        {
            if (token == null)
            {
                return null;
            }

            foreach (var key in keys)
            {
                var candidate = token[key];
                if (candidate == null || candidate.Type == JTokenType.Null)
                {
                    continue;
                }

                var text = candidate.ToString().Trim();
                if (decimal.TryParse(text, NumberStyles.Any, CultureInfo.InvariantCulture, out var value)
                    || decimal.TryParse(text, NumberStyles.Any, CultureInfo.CurrentCulture, out value))
                {
                    return value;
                }
            }

            return null;
        }

        private static DateTime? GetTokenDate(JToken? token, params string[] keys)
        {
            if (token == null)
            {
                return null;
            }

            foreach (var key in keys)
            {
                var candidate = token[key];
                if (candidate == null || candidate.Type == JTokenType.Null)
                {
                    continue;
                }

                if (candidate.Type == JTokenType.Date)
                {
                    var dateValue = candidate.Value<DateTime>();
                    if (IsValidVoucherDate(dateValue))
                    {
                        return dateValue.Date;
                    }

                    continue;
                }

                if ((candidate.Type == JTokenType.Integer || candidate.Type == JTokenType.Float)
                    && long.TryParse(candidate.ToString(), NumberStyles.Any, CultureInfo.InvariantCulture, out var epochNumber))
                {
                    var epochDate = TryParseUnixDate(epochNumber);
                    if (epochDate.HasValue)
                    {
                        return epochDate.Value.Date;
                    }
                }

                if (TryParseFlexibleDate(candidate.ToString(), out var parsedDate))
                {
                    return parsedDate.Date;
                }
            }

            return null;
        }

        private static bool TryParseFlexibleDate(string? value, out DateTime parsedDate)
        {
            parsedDate = default;
            if (string.IsNullOrWhiteSpace(value))
            {
                return false;
            }

            var text = value.Trim();
            if (long.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out var epochNumber))
            {
                var epochDate = TryParseUnixDate(epochNumber);
                if (epochDate.HasValue)
                {
                    parsedDate = epochDate.Value;
                    return true;
                }
            }

            string[] formats =
            {
                "yyyy-MM-dd",
                "yyyy/MM/dd",
                "dd-MM-yyyy",
                "dd/MM/yyyy",
                "MM/dd/yyyy",
                "yyyyMMdd",
                "ddMMyyyy",
                "dd-MMM-yyyy",
                "dd MMM yyyy",
                "yyyy-MM-ddTHH:mm:ss",
                "yyyy-MM-ddTHH:mm:ssZ",
                "yyyy-MM-ddTHH:mm:ss.fffZ",
                "yyyy-MM-ddTHH:mm:ss.fffffffZ",
                "yyyy-MM-ddTHH:mm:ssK",
                "yyyy-MM-ddTHH:mm:ss.fffK",
                "o"
            };

            if (DateTime.TryParseExact(text, formats, CultureInfo.InvariantCulture, DateTimeStyles.AllowWhiteSpaces, out parsedDate)
                || DateTime.TryParse(text, CultureInfo.InvariantCulture, DateTimeStyles.AllowWhiteSpaces, out parsedDate)
                || DateTime.TryParse(text, CultureInfo.CurrentCulture, DateTimeStyles.AllowWhiteSpaces, out parsedDate))
            {
                if (IsValidVoucherDate(parsedDate))
                {
                    parsedDate = parsedDate.Date;
                    return true;
                }
            }

            return false;
        }

        private static DateTime? TryParseUnixDate(long rawValue)
        {
            if (rawValue <= 0)
            {
                return null;
            }

            try
            {
                DateTime date;
                // >= 13 digits is typically Unix milliseconds
                if (rawValue >= 1000000000000)
                {
                    date = DateTimeOffset.FromUnixTimeMilliseconds(rawValue).LocalDateTime;
                }
                else
                {
                    date = DateTimeOffset.FromUnixTimeSeconds(rawValue).LocalDateTime;
                }

                return IsValidVoucherDate(date) ? date.Date : null;
            }
            catch
            {
                return null;
            }
        }

        private static bool IsValidVoucherDate(DateTime value)
        {
            if (value == DateTime.MinValue || value == DateTime.MaxValue)
            {
                return false;
            }

            var year = value.Year;
            return year >= 1900 && year <= DateTime.Today.Year + 10;
        }
        private static bool IsVoucherDateMissingError(string? message)
        {
            if (string.IsNullOrWhiteSpace(message))
            {
                return false;
            }

            var normalized = message.Trim();
            return normalized.IndexOf("voucher date", StringComparison.OrdinalIgnoreCase) >= 0
                && normalized.IndexOf("missing", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        private static bool? GetTokenBool(JToken? token, params string[] keys)
        {
            if (token == null)
            {
                return null;
            }

            foreach (var key in keys)
            {
                var candidate = token[key];
                if (candidate == null || candidate.Type == JTokenType.Null)
                {
                    continue;
                }

                if (candidate.Type == JTokenType.Boolean)
                {
                    return candidate.Value<bool>();
                }

                var text = candidate.ToString().Trim();
                if (bool.TryParse(text, out var boolValue))
                {
                    return boolValue;
                }

                if (text.Equals("dr", StringComparison.OrdinalIgnoreCase)
                    || text.Equals("debit", StringComparison.OrdinalIgnoreCase))
                {
                    return true;
                }

                if (text.Equals("cr", StringComparison.OrdinalIgnoreCase)
                    || text.Equals("credit", StringComparison.OrdinalIgnoreCase))
                {
                    return false;
                }
            }

            return null;
        }

        private static List<JToken> GetTokenArrayItems(JToken? token, params string[] keys)
        {
            var output = new List<JToken>();
            if (token == null)
            {
                return output;
            }

            foreach (var key in keys)
            {
                var candidate = token[key];
                if (candidate == null || candidate.Type == JTokenType.Null)
                {
                    continue;
                }

                if (candidate is JArray array)
                {
                    output.AddRange(array.Where(item => item != null));
                }
                else if (candidate is JObject obj)
                {
                    output.Add(obj);
                }
            }

            return output;
        }

        private static List<VoucherInventoryEntry> ExtractInventoryEntries(JToken? voucherToken)
        {
            var rows = GetTokenArrayItems(voucherToken, "items", "stock_entries", "inventory_entries", "stockEntries", "inventoryEntries");
            var output = new List<VoucherInventoryEntry>();

            foreach (var row in rows)
            {
                var stockName = GetTokenString(row, "stock_item_name", "stock_item", "item_name", "product_name", "description", "name");
                if (string.IsNullOrWhiteSpace(stockName))
                {
                    continue;
                }

                var qty = GetTokenDecimal(row, "quantity", "qty") ?? 0m;
                var rate = GetTokenDecimal(row, "rate") ?? 0m;
                var amount = GetTokenDecimal(row, "amount", "total_amount", "total", "totalAmount", "baseAmount") ?? 0m;

                if (amount <= 0 && qty > 0 && rate > 0)
                {
                    amount = qty * rate;
                }

                if (rate <= 0 && qty > 0 && amount > 0)
                {
                    rate = amount / qty;
                }

                if (qty <= 0 && rate > 0 && amount > 0)
                {
                    qty = amount / rate;
                }

                if (qty <= 0 && amount > 0)
                {
                    qty = 1m;
                }

                if (amount <= 0)
                {
                    continue;
                }

                var taxRate = GetTokenDecimal(row, "tax_rate", "gst_rate", "gstRate");

                output.Add(new VoucherInventoryEntry
                {
                    StockItemName = stockName,
                    Quantity = Math.Abs(qty),
                    Unit = GetTokenString(row, "unit", "uom") ?? "Nos",
                    Rate = Math.Abs(rate),
                    Amount = Math.Abs(amount),
                    DiscountPercent = Math.Abs(GetTokenDecimal(row, "discount_percent", "discountPercent", "discount") ?? 0m),
                    HsnCode = GetTokenString(row, "hsn_code", "hsn", "hsnCode"),
                    TaxRate = taxRate,
                    Taxability = GetTokenString(row, "taxability")
                });
            }

            return output;
        }

        private static List<VoucherLedgerEntry> ExtractLedgerEntries(JToken? voucherToken)
        {
            var rows = GetTokenArrayItems(voucherToken, "ledger_entries", "ledgerEntries", "entries");
            var output = new List<VoucherLedgerEntry>();

            foreach (var row in rows)
            {
                var ledgerName = GetTokenString(row, "ledger_name", "ledgerName", "name", "account_name", "accountName");
                if (string.IsNullOrWhiteSpace(ledgerName))
                {
                    continue;
                }

                var rawAmount = GetTokenDecimal(row, "amount", "total_amount", "total", "value") ?? 0m;
                if (rawAmount == 0)
                {
                    continue;
                }

                var isDebit = GetTokenBool(row, "is_debit", "isDebit");
                if (!isDebit.HasValue)
                {
                    var typeText = GetTokenString(row, "type", "dr_cr", "entry_type");
                    if (!string.IsNullOrWhiteSpace(typeText))
                    {
                        if (typeText.StartsWith("D", StringComparison.OrdinalIgnoreCase))
                        {
                            isDebit = true;
                        }
                        else if (typeText.StartsWith("C", StringComparison.OrdinalIgnoreCase))
                        {
                            isDebit = false;
                        }
                    }
                }

                var debit = isDebit ?? (rawAmount < 0);
                var signedAmount = debit ? -Math.Abs(rawAmount) : Math.Abs(rawAmount);

                output.Add(new VoucherLedgerEntry
                {
                    LedgerName = ledgerName,
                    Amount = signedAmount,
                    IsDebit = debit
                });
            }

            return output;
        }

        private static int GetRetryAttempt(PendingTransaction transaction)
        {
            if (transaction.RetryCount > 0)
            {
                return transaction.RetryCount;
            }

            if (string.IsNullOrWhiteSpace(transaction.ErrorMessage))
            {
                return 0;
            }

            var match = RetryTagRegex.Match(transaction.ErrorMessage);
            return match.Success && int.TryParse(match.Groups[1].Value, out var parsedAttempt)
                ? parsedAttempt
                : 0;
        }

        private static string AppendRetryMetadata(string? message, int attempt)
        {
            var clean = string.IsNullOrWhiteSpace(message)
                ? "Unknown error"
                : RetryTagRegex.Replace(message, string.Empty).Trim();

            return $"{clean} [retry {attempt}/{MaxPendingPushRetries}]";
        }

        /// <summary>
        /// Normalize voucher type from database format to valid Tally voucher type.
        /// Database may store table names like "VOUCHERS" or generic types.
        /// Tally requires exact type names: Sales, Purchase, Receipt, Payment, Journal, etc.
        /// </summary>
        private string NormalizeTallyVoucherType(string rawType, dynamic voucherData)
        {
            if (string.IsNullOrEmpty(rawType)) return "Receipt";

            // 1. First try to get the actual voucher type from the voucher data itself
            string? typeFromData = null;
            try
            {
                typeFromData = voucherData?.voucher_type_name?.ToString() ??
                               voucherData?.voucherTypeName?.ToString() ??
                               voucherData?.voucher_type?.ToString() ??
                               voucherData?.voucherType?.ToString() ??
                               voucherData?.type?.ToString();
            }
            catch { /* dynamic access may fail, ignore */ }

            // If we found a type in voucher data and it's a valid Tally type, use it
            if (!string.IsNullOrEmpty(typeFromData))
            {
                var normalizedFromData = MapToTallyType(typeFromData);
                if (normalizedFromData != null)
                {
                    SyncLogger.Log($"   ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â°ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¸ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â¦ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã¢â‚¬Å“ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â½ Resolved voucher type from data: '{rawType}' ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¾ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ '{normalizedFromData}'");
                    return normalizedFromData;
                }
            }

            // 2. Try to map the raw type directly
            var mapped = MapToTallyType(rawType);
            if (mapped != null) return mapped;

            // 3. If type is generic (VOUCHERS, TRANSACTION, etc.), try to infer from data shape
            var upperType = rawType.Trim().ToUpper();
            if (upperType == "VOUCHERS" || upperType == "TRANSACTION" || upperType == "ENTRY")
            {
                // Try to infer from amount sign or available fields
                try
                {
                    bool hasItems = voucherData?.items != null;
                    string? cashBankLedger = voucherData?.cash_bank_ledger?.ToString();

                    if (hasItems)
                    {
                        // Has inventory items ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¾ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ likely Sales or Purchase
                        return "Sales";
                    }
                    else if (!string.IsNullOrEmpty(cashBankLedger))
                    {
                        // Has cash/bank ledger ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Â ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¡ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¬ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€¦Ã‚Â¾ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â¢ likely Receipt or Payment
                        return "Receipt";
                    }
                }
                catch { /* dynamic access may fail */ }

                // Default fallback for generic types
